<script setup lang="ts">
import AudioRetryNotice from './AudioRetryNotice.vue';
import {computed} from 'vue';
import {meaningOptionLabels,shortMeaning} from '../services/meaning-presentation';
import type {Question} from '@jp/core';import type {QuizAttempt} from '@jp/models';import {Volume2,Check,X} from 'lucide-vue-next';
const props=defineProps<{compactMeaning?:boolean;question:Question;attempt:QuizAttempt|null;heard:boolean;busy:boolean;audioError:string;speaking:boolean}>();defineEmits<{choose:[value:string|null];play:[slow:boolean]}>();
const optionLabels=computed(()=>props.compactMeaning&&props.question.type!=='kanji-reading'?meaningOptionLabels(props.question.options):props.question.options);
const answerLabel=computed(()=>optionLabels.value[props.question.options.indexOf(props.question.correct)]??(props.compactMeaning?shortMeaning(props.question.correct):props.question.correct));
const labels={'kana-meaning':'根据假名，选择正确的中文释义','kanji-reading':'根据汉字，选择正确的平假名','audio-meaning':'听一听，选择正确的中文释义'};
</script>
<template><div class="quiz-question"><p class="quiz-instruction">{{labels[question.type]}}</p><div v-if="question.type==='audio-meaning'" class="listening-prompt"><button class="listen-button" :disabled="busy" @click="$emit('play',false)"><Volume2 :size="32"/><span>{{speaking?'正在播放…':'播放读音'}}</span></button><button class="slow-listen" :disabled="busy" @click="$emit('play',true)">慢速播放</button><p v-if="!heard" class="muted">播放后即可选择答案</p></div><div v-else class="word-face quiz-prompt" lang="ja"><h1>{{question.prompt}}</h1></div><AudioRetryNotice :error="audioError" :disabled="busy" @retry="$emit('play',false)" /><div class="quiz-options" role="group" aria-label="答案选项"><button v-for="(option,i) in question.options" :key="option" :disabled="busy||!!attempt||(question.type==='audio-meaning'&&(!heard||!!audioError))" :class="{'option-correct':attempt&&option===question.correct,'option-wrong':attempt&&!attempt.isCorrect&&option===attempt.selected}" @click="$emit('choose',option)"><kbd>{{i+1}}</kbd><span :title="compactMeaning?option:undefined">{{optionLabels[i]}}</span><Check v-if="attempt&&option===question.correct" :size="20"/><X v-else-if="attempt&&option===attempt.selected" :size="20"/></button></div><button v-if="!attempt" class="dont-know" :disabled="busy||(question.type==='audio-meaning'&&(!heard||!!audioError))" @click="$emit('choose',null)">不认识，查看解析</button><div v-if="attempt" class="quiz-feedback" :class="{incorrect:!attempt.isCorrect}" role="status"><strong>{{attempt.isCorrect?'答对了':'再记住一次'}}</strong><span v-if="!attempt.isCorrect">正确答案：{{answerLabel}}</span><span v-else>继续巩固这份记忆。</span></div></div></template>
